css:
.card {
 font-family: "ヒラギノ角ゴ Pro W3", "Hiragino Kaku Gothic Pro", "Noto Sans JP", "Noto Sans CJK JP", Osaka, "メイリオ", Meiryo, "ＭＳ Ｐゴシック", "MS PGothic", "MS UI Gothic", sans-serif;
 font-size: 44px;
 text-align: center;
}

img {
max-width: 300px;
max-height: 250px;
}

.mobile img {
max-width: 50vw;
}

/* Prevents the furigana from being selected */
ruby > rt {
	user-select: none;
}

/* This part defines the bold color. */
b{color: #5586cd}
ruby {ruby-position:over;} ruby > rt {font-size:0.45em;line-height:1.2;} .meaning,.sentence,.picture {margin-top:12px;} .meaning,.sentence-meaning {font-size:25px;padding-bottom:20px;} .notes {font-size:20px;margin-top:12px;}
